setup:
MUTATE {
  CREATE CONCEPT ?a { TYPE "Person" NAME "Al" SET FIELDS {key: "al"} }
  CREATE CONCEPT ?b { TYPE "Person" NAME "Alice" SET FIELDS {key: "alice"} }
  CREATE CONCEPT ?dark { TYPE "Option" NAME "Dark" SET FIELDS {key: "dark"} }
  ENSURE PROPOSITION ?old (?a, "prefers", ?dark)
}

MERGE CONCEPT ?source INTO ?target WHERE {
  ?source CONCEPT {key: "al"}
  ?target CONCEPT {key: "alice"}
}

MUTATE {
  UPSERT CONCEPT ?a { MATCH {type: "Person", key: "al"} }
  UPSERT CONCEPT ?dark { MATCH {type: "Option", key: "dark"} }
  ENSURE PROPOSITION ?new (?a, "prefers", ?dark)
}

MUTATE {
  UPSERT CONCEPT ?a { MATCH {type: "Person", key: "al"} }
  UPSERT CONCEPT ?dark { MATCH {type: "Option", key: "dark"} }
  ENSURE PROPOSITION ?again (?a, "prefers", ?dark)
}

cases.command:
FIND(?merged.key) WHERE {
  ?c CONCEPT {key: "al", state: "merged"}
  ?merged CONCEPT {id: ?target}
  FILTER(?target == ?c.merged_into)
}

MERGE CONCEPT ?source INTO ?target WHERE {
  ?source CONCEPT {key: "al", state: "merged"}
  ?target CONCEPT {key: "alice"}
}

MERGE CONCEPT ?source INTO ?target WHERE {
  ?source CONCEPT {key: "alice"}
  ?target CONCEPT {key: "al", state: "merged"}
}

MERGE CONCEPT ?source INTO ?target WHERE {
  ?source CONCEPT {key: "alice"}
  ?target CONCEPT {key: "alice"}
}
